  final TextEditingController _note = TextEditingController();

  StayQuote? _quote;
  bool _loading = true;
  bool _quoting = false;
  bool _submitting = false;
  String? _error;
  String? _quoteError;

  @override
  void initState() {
    super.initState();
    _load();
  }

  // ⚠ THE SCREEN HAD NO dispose AT ALL until 29 August 2026, because it had no
