  @override
  void dispose() {
    _note.dispose();
    super.dispose();
  }

  Future<void> _load() async {
    try {
      final StayBooking? b =
          await StayBookingService.instance.byId(widget.bookingId);
      if (b == null) {
        if (!mounted) return;
        setState(() {
          _loading = false;
          _error = 'This booking could not be found.';
        });
        return;
      }
      final StayListing? l =
          await StayListingService.instance.byId(b.listingId);
      if (!mounted) return;
      setState(() {
        _booking = b;
        _listing = l;
        _checkIn = b.checkIn;
        _checkOut = b.checkOut;
        _adults = b.guests.adults;
        _children = b.guests.children;
        _infants = b.guests.infants;
        _loading = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _loading = false;
        _error = e.toString();
      });
    }
  }

  bool get _changed {
    final StayBooking? b = _booking;
    if (b == null) return false;
    return !_sameDay(_checkIn, b.checkIn) ||
        !_sameDay(_checkOut, b.checkOut) ||
        _adults != b.guests.adults ||
        _children != b.guests.children ||
        _infants != b.guests.infants;
  }

  bool get _datesChanged {
    final StayBooking? b = _booking;
    if (b == null) return false;
    return !_sameDay(_checkIn, b.checkIn) || !_sameDay(_checkOut, b.checkOut);
  }

  /// True when a confirmed stay would go back to pending.
  ///
  /// Mirrors amendStayBooking exactly: request mode AND dates changed AND the
  /// booking is currently confirmed. A pending booking is already pending, so
  /// there is nothing to warn about.
  bool get _wouldNeedHostAgain =>
      _datesChanged &&
      (_listing?.bookingMode ?? BookingMode.request) == BookingMode.request &&
      _booking?.status == BookingStatus.confirmed;

  static bool _sameDay(DateTime? a, DateTime? b) =>
      a != null &&
      b != null &&
      a.year == b.year &&
      a.month == b.month &&
      a.day == b.day;

  Future<void> _requote() async {
    if (!_changed || _checkIn == null || _checkOut == null) {
      setState(() {
        _quote = null;
        _quoteError = null;
      });
      return;
    }
    setState(() {
      _quoting = true;
      _quoteError = null;
    });
    try {
      final q = await StayBookingService.instance.quoteAmendment(
        bookingId: widget.bookingId,
        checkIn: _checkIn,
        checkOut: _checkOut,
        adults: _adults,
        children: _children,
        infants: _infants,
      );
      if (!mounted) return;
      setState(() {
        _quote = q;
        _quoting = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _quoting = false;
        _quote = null;
        _quoteError = e.toString();
      });
    }
  }

