  // ── Price ────────────────────────────────────────────────────────────────

  Widget _priceCard() {
    if (!_changed) {
      return _card(
        Text(
          'Change your dates or party size to see the new price.',
          style: GoogleFonts.inter(
              fontSize: 14, color: GoOutsColors.bodyText),
        ),
      );
    }
    if (_quoting) {
      return _card(
        const Center(
          child: Padding(
            padding: EdgeInsets.symmetric(vertical: 12),
            child: CircularProgressIndicator(),
          ),
        ),
      );
    }
    if (_quoteError != null) {
      return _card(
        Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('This change could not be priced',
                style: GoogleFonts.inter(
                    fontSize: 15,
                    fontWeight: FontWeight.w700,
                    color: GoOutsColors.deepNavy)),
            const SizedBox(height: 6),
            Text(_quoteError!,
                style: GoogleFonts.inter(
                    fontSize: 13.5, color: GoOutsColors.bodyText)),
          ],
        ),
      );
    }

    final StayQuote? q = _quote;
    if (q == null) return const SizedBox.shrink();

    final int diff = q.total.value - (_booking?.pricing.total.value ?? 0);

    return _card(
      Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          if (!q.available) ...[
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Icon(Icons.event_busy,
                    size: 18, color: GoOutsColors.error),
                const SizedBox(width: 8),
