                  ),
                ),
              ],
            ),
            const SizedBox(height: 12),
          ],
          _row('New total', q.total.formatted),
          _row('Was', _booking?.pricing.total.formatted ?? '—'),
          const Divider(height: 20, color: GoOutsColors.dividerGray),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text(
